<template><div><Table :columns="columns" :data="records" no-data-text="暂无资质版本"><template slot="type" slot-scope="{row}"><strong>{{status(row.type)}}</strong><p class="ui-meta">{{status(row.scope)}} · v{{row.revision}}</p></template><template slot="state" slot-scope="{row}"><StatusTag :value="row.status"/><p v-if="row.warning" class="ui-meta">{{warning(row.warning)}}</p></template><template slot="valid" slot-scope="{row}">{{date(row.validFrom)}}<br/>至 {{row.longTerm?'长期有效':date(row.validTo)}}<p class="ui-meta" v-if="!row.longTerm">截止时点不含；按上海时间显示</p></template><template slot="operations" slot-scope="{row}"><Button size="small" @click="selected=row;show=true">证照与附件</Button><Button v-if="revocable&&row.status!=='REVOKED'" size="small" type="error" :disabled="disabled" @click="$emit('revoke',row)">撤销</Button></template></Table><Modal v-model="show" title="资质版本详情" width="920" footer-hide><div v-if="selected" class="s1-ui"><p class="ui-meta">资质编号 {{selected.id}} · 提交版本 {{selected.revision}} · 数据版本 {{selected.version}}</p><DetailSection title="证照事实"><FieldRow label="类型" :value="status(selected.type)"/><FieldRow label="范围" :value="status(selected.scope)"/><FieldRow label="证照编号" :value="details.number"/><FieldRow label="持有人／主体" :value="details.holder"/><FieldRow label="发证机关" :value="details.issuer"/><FieldRow label="批准时间" :value="date(selected.approvedAt)"/><FieldRow label="证照起期" :value="details.validFrom||date(selected.validFrom)"/><FieldRow label="证照止期" :value="selected.longTerm?'长期有效':details.validThrough||date(selected.validTo)"/><FieldRow label="撤销原因" :value="selected.revocationReason" wide/></DetailSection><CategoryNames v-if="selected.categoryIds&&selected.categoryIds.length" :ids="selected.categoryIds" :purpose="purpose"/><AttachmentList :key="selected.id" :value="details.fileIds||[]" purpose="QUALIFICATION"/></div></Modal></div></template>
<script>import {date,status} from '../display.cjs';import StatusTag from './StatusTag';import FieldRow from './FieldRow';import DetailSection from './DetailSection';import AttachmentList from './AttachmentList';import CategoryNames from './CategoryNames';export default {components:{StatusTag,FieldRow,DetailSection,AttachmentList,CategoryNames},props:{records:{type:Array,default:()=>[]},revocable:Boolean,disabled:Boolean,purpose:{type:String,default:'eligibility'}},data:()=>({show:false,selected:null,columns:[{title:'资质／版本',slot:'type',minWidth:170},{title:'状态',slot:'state',minWidth:120},{title:'有效期',slot:'valid',minWidth:210},{title:'操作',slot:'operations',minWidth:185}]}),computed:{details(){return this.selected&&this.selected.details||{};}},watch:{records(){this.show=false;this.selected=null;}},methods:{date,status,warning(value){return {WITHIN_30_DAYS:'30天内到期',WITHIN_7_DAYS:'7天内到期',EXPIRED:'已到期'}[value]||'请核查有效期';}}};</script>
